cat > /tmp/Program.cs << 'CEOF'
using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
var build = BinaryLog.ReadBuild(binlogPath);

var errors = new List<(string project, string code, string message, string file, int line)>();
var warnings = new List<(string project, string code, string message, string file, int line)>();

build.VisitAllChildren<Error>(e =>
{
    var proj = e.GetNearestParent<Project>()?.Name ?? "(unknown)";
    errors.Add((proj, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
});

build.VisitAllChildren<Warning>(w =>
{
    var proj = w.GetNearestParent<Project>()?.Name ?? "(unknown)";
    warnings.Add((proj, w.Code ?? "", w.Text ?? w.ToString(), w.File ?? "", w.LineNumber));
});

// Check for project build failures (dependency failures)
var failedProjects = new HashSet<string>();
build.VisitAllChildren<Project>(p =>
{
    // A project that has errors
    var hasErrors = false;
    p.VisitAllChildren<Error>(e => hasErrors = true);
    if (hasErrors) failedProjects.Add(p.Name);
});

Console.WriteLine("=== BUILD ERRORS ===");
Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

var grouped = errors.GroupBy(e => e.project);
foreach (var g in grouped)
{
    Console.WriteLine($"--- Project: {g.Key} ---");
    foreach (var e in g)
    {
        Console.WriteLine($"  [{e.code}] {e.message}");
        if (!string.IsNullOrEmpty(e.file))
            Console.WriteLine($"    File: {e.file}:{e.line}");
    }
    Console.WriteLine();
}

// Show dependency/reference errors specifically
Console.WriteLine("=== FAILED PROJECTS ===");
foreach (var p in failedProjects)
    Console.WriteLine($"  - {p}");

Console.WriteLine();
Console.WriteLine("=== RELEVANT WARNINGS ===");
foreach (var w in warnings.Where(w => w.code.StartsWith("CS") || w.code.StartsWith("NU") || w.code.StartsWith("MSB")))
{
    Console.WriteLine($"  [{w.code}] {w.project}: {w.message}");
}
