using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Extract project references and package references
build.VisitAllChildren<Project>(p =>
{
    Console.WriteLine($"=== Project: {p.Name} ===");

    // Look for items
    p.VisitAllChildren<Item>(item =>
    {
        if (item.Name?.Contains("PackageReference") == true || 
            item.Name?.Contains("Reference") == true ||
            item.Name?.Contains("ProjectReference") == true)
        {
            Console.WriteLine($"  {item.Name}: {item.Text}");
        }
    });

    // Look for added items via AddItem
    p.VisitAllChildren<AddItem>(ai =>
    {
        if (ai.Name?.Contains("PackageReference") == true ||
            ai.Name?.Contains("ProjectReference") == true)
        {
            Console.WriteLine($"  [AddItem] {ai.Name}:");
            foreach (var child in ai.Children)
                Console.WriteLine($"    {child}");
        }
    });
});

// Also look for source file contents that might reveal what's needed
Console.WriteLine("\n=== Source file references in errors ===");
build.VisitAllChildren<Error>(e =>
{
    Console.WriteLine($"File: {e.File}:{e.LineNumber} => {e.Text}");
});
