using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Gather all messages to find NuGet restore info
var messages = new List<string>();
build.VisitAllChildren<Message>(m => {
    var t = m.Text ?? "";
    if (t.Contains("Newtonsoft") || t.Contains("PackageReference") || t.Contains("package") || t.Contains("restore"))
        messages.Add(t);
});

Console.WriteLine("=== NuGet / Package related messages ===");
foreach (var m in messages.Take(30))
    Console.WriteLine($"  {m}");

// Find project references
Console.WriteLine("\n=== Project dependency graph ===");
build.VisitAllChildren<Project>(p =>
{
    p.VisitAllChildren<AddItem>(ai =>
    {
        if (ai.Name == "ProjectReference")
        {
            Console.WriteLine($"  {p.Name} -> ProjectReference:");
            foreach (var c in ai.Children)
                Console.WriteLine($"    {c}");
        }
    });
    p.VisitAllChildren<AddItem>(ai =>
    {
        if (ai.Name == "PackageReference")
        {
            Console.WriteLine($"  {p.Name} -> PackageReference:");
            foreach (var c in ai.Children)
                Console.WriteLine($"    {c}");
        }
    });
});

// Check for source file contents embedded in messages
Console.WriteLine("\n=== CSC command lines ===");
build.VisitAllChildren<Task>(t => {
    if (t.Name == "Csc")
    {
        var proj = t.GetNearestParent<Project>()?.Name ?? "?";
        Console.WriteLine($"  Project: {proj}");
        t.VisitAllChildren<Message>(m => {
            if (m.Text?.Contains("/reference:") == true || m.Text?.Contains("Newtonsoft") == true)
                Console.WriteLine($"    {m.Text?.Substring(0, Math.Min(200, m.Text.Length))}");
        });
    }
});
